import 'package:flutter/material.dart';
import 'package:salomon_bottom_bar/salomon_bottom_bar.dart';

class FancyBar extends StatefulWidget {
  FancyBar({super.key});

  @override
  State<FancyBar> createState() => _FancyBarState();
}

class _FancyBarState extends State<FancyBar> {
  @override
  Widget build(BuildContext context) => SalomonBottomBar(
    items: [
      SalomonBottomBarItem(icon: const Icon(Icons.home), title: const Text('Café')),
      SalomonBottomBarItem(icon: const Icon(Icons.star), title: const Text('Stars')),
    ],
  );
}
